import time

from common import db


while True:
    connection = db()
    try:
        connection.execute("BEGIN IMMEDIATE")
        row = connection.execute(
            "SELECT id, payload FROM jobs "
            "WHERE status = 'queued' ORDER BY rowid LIMIT 1"
        ).fetchone()
        if row is None:
            connection.commit()
        else:
            connection.execute(
                "UPDATE jobs SET status = 'completed', result = ?, "
                "attempts = attempts + 1 WHERE id = ? AND status = 'queued'",
                ("processed:" + row["payload"], row["id"]),
            )
            connection.commit()
    except Exception:
        connection.rollback()
        time.sleep(0.1)
    finally:
        connection.close()
    if row is None:
        time.sleep(0.1)

